Here is a simple banking app in Python:

```python
# Initialize accounts and balance
accounts = [{"name": "John", "balance": 100}, {"name": "Jane", "balance": 200}]

def show_accounts():
    for account in accounts:
        print(f"Name: {account['name']}")
        print(f"Balance {account['balance']}")

def deposit(name, amount):
    for account in accounts:
        if account["name"] == name:
            account["balance"] += amount
            print(f"{amount} deposited. New balance is {account['balance']}")

def withdraw(name, amount):
    for account in accounts:
        if account["name"] == name:
            if account["balance"] >= amount:
                account["balance"] -= amount
                print(f"{amount} withdrawn. New balance is {account['balance']}")
            else:
                print("Insufficient funds")

# App starts here            
while True:
    print("1 - Show Accounts")
    print("2 - Deposit")    
    print("3 - Withdraw")
    print("0 - Exit")

    option = int(input("Enter option: "))

    if option == 1:
        show_accounts()

    elif option == 2:
        name = input("Enter name: ")
        amount = float(input("Enter amount to deposit: "))
        deposit(name, amount)

    elif option == 3:
        name = input("Enter name: ")
        amount = float(input("Enter amount to withdraw: "))
        withdraw(name, amount)

    elif option == 0:
        break
```

