            CartAndFavAdd selectedEvent = getSelectedEventFromButton(addToFavButton);
            sendAddToFavouriteRequest(selectedEvent);
        });

        addToCartButton.setOnAction(event -> {
            CartAndFavAdd selectedEvent = getSelectedEventFromButton(addToCartButton);
            sendAddToCartRequest(selectedEvent);
        });

        VBox buttonsVBox = new VBox();
        buttonsVBox.getChildren().addAll(addToFavButton, addToCartButton);

        buttonsBox.getChildren().add(buttonsVBox);
        return buttonsBox;
    }

    private CartAndFavAdd getSelectedEventFromButton(Button button) {
        HBox listItem = (HBox) button.getParent();
        VBox eventInfoBox = (VBox) listItem.getChildren().get(0);

        Label nameLabel = (Label) eventInfoBox.getChildren().get(0);
        HBox dateCategoryBox = (HBox) eventInfoBox.getChildren().get(1);
        Label dateLabel = (Label) dateCategoryBox.getChildren().get(0);
        Label categoryLabel = (Label) dateCategoryBox.getChildren().get(1);

        VBox placeSeatsBox = (VBox) eventInfoBox.getChildren().get(2);
        Label placeLabel = (Label) placeSeatsBox.getChildren().get(0);

        String eventName = nameLabel.getText();
        String eventDate = dateLabel.getText().replace("Date: ", "");

        String placeLabelText = placeLabel.getText().replace("Place: ", "");
        String[] placeComponents = placeLabelText.split(", ");
        String eventStreet = placeComponents[0];
        String eventCity = placeComponents[1];

        return new CartAndFavAdd(userSession.getId(), eventName, eventDate, eventStreet, eventCity);
    }


    private void sendAddToFavouriteRequest(CartAndFavAdd event) {
        MessageContainer<CartAndFavAdd> addToFavouriteRequest = new MessageContainer<>("ADD_TO_FAVOURITE", event);
        clientConnection.sendDataToServer(addToFavouriteRequest);
    }

    private void sendAddToCartRequest(CartAndFavAdd event) {
        MessageContainer<CartAndFavAdd> addToCartRequest = new MessageContainer<>("ADD_TO_CART", event);
        clientConnection.sendDataToServer(addToCartRequest);
    }

    private Button createButton(String text) {
        Button button = new Button(text);
        button.getStyleClass().add("transparent-button");
        return button;
    }

